<style lang="less" scoped>
.welcome-container {
  height: 200px;
  width: 100%;
}

.animated-signature {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;

  path {
    stroke-dasharray: 2400;
    stroke-dashoffset: 2400;
    fill: transparent;
    animation: drawSignature 8s linear infinite both;
    stroke-width: 2px;
    stroke: black;
  }
}

@keyframes drawSignature {
  0% {
    stroke-dashoffset: 2400;
  }

  15% {
    fill: transparent;
  }

  35%,
  75% {
    stroke-dashoffset: 0;
    fill: black;
  }

  90%,
  to {
    stroke-dashoffset: 2400;
    fill: transparent;
  }
}
</style>